/**
 * Pinned npm-локфайлы (package-lock.json, lockfileVersion 3) для npm-артефактов.
 * Генерируются на момент бампа версии инструмента: `npm install --package-lock-only
 * --omit=dev --no-audit --no-fund` из toolchain-node, затем base64.
 * npm ci на установке проверяет integrity каждого пакета — ни один байт
 * зависимостей не исполняется без верификации (supply-chain; обзор 2026-08-06).
 *
 * Ключ: '<tool>@<version>'.
 * Обновление: bash scripts/regen-omp-lock.sh <version> (см. header installera).
 */

const NPM_LOCKS_B64: Record<string, string> = {
  // @oh-my-pi/pi-coding-agent 17.2.10 — 202 integrity-записи, проверено `npm ci`.
  'omp@17.2.10':
    '',
};

/** Декодированный package-lock.json по ключу `<tool>@<version>`, или null. */
export function getNpmLock(tool: string, version: string): string | null {
  const b64 = NPM_LOCKS_B64[`${tool}@${version}`];
  if (!b64) return null;
  return Buffer.from(b64, 'base64').toString('utf8');
}
